package com._8x8.herd.device_logs.contract;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The S3 object key of one uploaded file: {@code raw/<mac>/<yyyy-mm-dd>/<HHmmssSSS>Z-<type>}, using the server UTC
 * receive time and the base type ({@code app.log}, not {@code now-app.log}).
 * <p>
 * The upload service formats the key before streaming to S3. The processor parses it back into MAC, time and type.
 * Tests check that {@code parse(format(key))} equals {@code key}, so both sides always agree.
 * <p>
 * {@code receivedAt} is cut to milliseconds, because that is all the key holds. The MAC and the type cannot be
 * {@code null}.
 */
public record ObjectKey(MacAddress mac, Instant receivedAt, FileType type) {

    private static final String PREFIX = "raw/";
    private static final Pattern KEY = Pattern.compile(PREFIX + "([0-9a-f]{12})/(\\d{4}-\\d{2}-\\d{2})/(\\d{9})Z-(.+)");
    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd").withZone(ZoneOffset.UTC);
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HHmmssSSS").withZone(ZoneOffset.UTC);
    private static final DateTimeFormatter TIME_PARSER = DateTimeFormatter.ofPattern("HHmmssSSS")
            .withResolverStyle(ResolverStyle.STRICT);

    public ObjectKey {
        Objects.requireNonNull(mac, "mac");
        Objects.requireNonNull(type, "type");
        receivedAt = Objects.requireNonNull(receivedAt, "receivedAt").truncatedTo(ChronoUnit.MILLIS);
    }

    /**
     * The S3 key for this upload, for example {@code raw/0004f2abcdef/2026-10-21/134512345Z-app.log}.
     */
    public String format() {
        return PREFIX + mac.lowercase() + "/" + DATE.format(receivedAt) + "/" + TIME.format(receivedAt) + "Z-"
                + type.suffix();
    }

    /**
     * Parses an S3 key back into its MAC, receive time and type. It accepts exactly what {@link #format} produces, so
     * {@code parse(key.format())} gives back a key equal to {@code key}.
     * <p>
     * Normal case: {@code raw/0004f2abcdef/2026-10-21/134512345Z-app.log} parses to MAC {@code 0004f2abcdef}, the
     * instant {@code 2026-10-21T13:45:12.345Z} and {@link FileType#APP_LOG}.
     * <p>
     * An empty result means the key is rejected. This is expected for bad input, so this method never throws. The
     * cases that are rejected:
     * <ul>
     * <li>{@code null}, an empty string, or text before or after the key, such as a path segment or a trailing slash
     * <li>a missing {@code raw/} prefix
     * <li>a MAC that is not 12 lowercase hex digits (an uppercase MAC is rejected here, unlike in file names)
     * <li>a date or time that does not exist, such as {@code 2026-02-30} or {@code 240000000Z}
     * <li>a time that is not 9 digits, or that is missing the {@code Z}
     * <li>an unknown type suffix, or {@code now-app.log}. A manual upload is recorded in the metadata, not in the key.
     * </ul>
     */
    public static Optional<ObjectKey> parse(String key) {
        if (key == null) {
            return Optional.empty();
        }
        Matcher shape = KEY.matcher(key);
        if (!shape.matches()) {
            return Optional.empty();
        }
        Optional<MacAddress> mac = MacAddress.parse(shape.group(1));
        Optional<FileType> type = FileType.fromSuffix(shape.group(4));
        if (mac.isEmpty() || type.isEmpty()) {
            return Optional.empty();
        }
        try {
            LocalDate date = LocalDate.parse(shape.group(2));
            LocalTime time = LocalTime.parse(shape.group(3), TIME_PARSER);
            return Optional.of(new ObjectKey(mac.get(), date.atTime(time).toInstant(ZoneOffset.UTC), type.get()));
        } catch (DateTimeParseException e) {
            return Optional.empty();
        }
    }
}
